inline PinSpan Pins(Route r) {
    switch (r) {
    case Route::Krauser: return {kKrauserPins, std::size(kKrauserPins)};
    case Route::Bats: return {kBatsPins, std::size(kBatsPins)};
    case Route::Cart: return {kCartPins, std::size(kCartPins)};
    case Route::Tree: return {kTreePins, std::size(kTreePins)};
    default: return {};
    }
}
template <class Mem> bool Qualify(Mem& m, uint32_t base, Route r) {
    const auto pins = Pins(r);
    if (!pins.count) return false;
    for (size_t i = 0; i < pins.count; ++i)
        if (!native_pins::Matches(m, base, pins.data[i].rva, pins.data[i].hex)) return false;
    return true;
}
