// Exactly the read-only part of em39GetCliffPos: pG+4F30 -> count, entries +8,
// type byte, position +4/+8/+C, stride 0x40. Never call the native writer.
enum class CliffResult {Clear, Near, Fault};
template <class Mem> CliffResult Cliff(Mem& m, uint32_t base, const float* player) {
    uint32_t global = 0, emi = 0;
    int32_t count = 0;
    if (!std::isfinite(player[0]) || !std::isfinite(player[2]) ||
        !m.Read(base + 0x806F3C, &global, 4) || !shield::Range(global, 0x4F34) ||
        !m.Read(global + 0x4F30, &emi, 4)) return CliffResult::Fault;
    if (!emi) return CliffResult::Clear;
    if (!m.Read(emi, &count, 4) || count < 0 || count > 4096 ||
        !shield::Range(emi, 8 + static_cast<size_t>(count) * 64)) return CliffResult::Fault;
    for (int32_t i = 0; i < count; ++i) {
        const uint32_t at = emi + 8 + static_cast<uint32_t>(i) * 64;
        uint8_t type = 0;
        if (!m.Read(at, &type, 1)) return CliffResult::Fault;
        if (type != 0xD) continue;
        float p[3]{};
        if (!m.Read(at + 4, p, sizeof(p)) || !std::isfinite(p[0]) || !std::isfinite(p[2])) return CliffResult::Fault;
        const double x = double(p[0]) - player[0], z = double(p[2]) - player[2];
        const float distance = static_cast<float>(x * x + z * z);
        if (!std::isfinite(distance)) return CliffResult::Fault;
        if (distance <= 4000000.f) return CliffResult::Near;
    }
    uint32_t again = 0;
    int32_t count_again = 0;
    if (!m.Read(global + 0x4F30, &again, 4) || again != emi ||
        !m.Read(emi, &count_again, 4) || count_again != count) return CliffResult::Fault;
    return CliffResult::Clear;
}
